  function renderTools(){const items=state.capabilities;if(!state.remote.capabilities?.ok){const message=empty("Capability Registry 不可用",state.remote.capabilities?.error?.message||"无法读取工具清单。","unavailable");$("#toolsContent").innerHTML=message;$("#capabilityList").innerHTML=message;return}const rows=items.map(x=>{const status=capabilityStatus(x);return `<tr data-inspect='${esc(JSON.stringify(x))}' tabindex="0"><td>${esc(x.id||x.name||"–")}</td><td>${esc(x.detail||"未提供能力说明")}</td><td>${esc(x.domain||"–")}</td><td>${esc(x.version||"–")}</td><td>${esc(x.execution_backend||"未提供")}</td><td>${x.available===true?"可执行":x.available===false?"未安装":"未知"}</td><td>${x.configured===true?"已配置":x.configured===false?"未配置":"未提供"}</td><td>${x.sandbox_ready===true?"就绪":x.sandbox_ready===false?"未就绪":"未提供"}</td><td><span class="${stateClass(status)}">${esc(status)}</span></td></tr>`});$("#toolsContent").innerHTML=items.length?`<article class="panel"><p class="trust-note">已安装、可执行、已配置、沙箱就绪与可安全执行是不同状态；注册表不证明工具已运行或产出有效结果。</p>${table(["Tool","Capability","Domain","Version","Execution Backend","Executable","Configured","Sandbox","Readiness"],rows)}</article>`:empty("Capability Registry 为空","后端没有返回已注册能力。");$("#capabilityList").innerHTML=items.length?items.slice(0,12).map(x=>{const status=capabilityStatus(x);return `<button class="capability" data-inspect='${esc(JSON.stringify(x))}'><b>${esc(x.id||x.name||"–")}</b><small>${esc(x.version||x.detail||"未提供版本")}</small><span class="${stateClass(status)}">${esc(status)}</span></button>`}).join(""):empty("Registry 为空","暂无能力条目。");}
