    host.innerHTML=`<div class="asset-graph-boundary">${esc([data.boundary,...(data.notes||[])].filter(Boolean).join(" · ")||"关系仅来自持久化 Observation，未观察到不等于已测试。")}</div><div class="asset-graph-stage" style="width:${width}px;height:${height}px;zoom:${state.graphScale}"><svg class="asset-graph-lines" width="${width}" height="${height}" aria-hidden="true">${paths}</svg>${nodes.map(node=>{const pos=positions.get(node.id),matched=match.includes(node);return `<button type="button" class="asset-node ${matched?"":"dimmed"}" data-node-id="${esc(node.id)}" style="left:${pos.x}px;top:${pos.y}px"><small>${esc(node.entity_type||"asset")}</small><strong>${esc(node.label||node.id)}</strong><em>${esc(node.attributes?.status||node.attributes?.scope_status||"未标注")}</em></button>`}).join("")}</div>`;
    $$(".asset-node",host).forEach(button=>{button.onclick=()=>renderGraphInspector(nodes.find(n=>n.id===button.dataset.nodeId));button.onmouseenter=()=>{const related=new Set([button.dataset.nodeId]);edges.filter(e=>e.source_id===button.dataset.nodeId||e.target_id===button.dataset.nodeId).forEach(e=>{related.add(e.source_id);related.add(e.target_id)});$$(".asset-node",host).forEach(n=>n.classList.toggle("related",related.has(n.dataset.nodeId)));$$(".asset-graph-lines path",host).forEach(path=>path.classList.toggle("related",path.dataset.source===button.dataset.nodeId||path.dataset.target===button.dataset.nodeId))};button.onmouseleave=()=>{$$(".asset-node.related,.asset-graph-lines path.related",host).forEach(n=>n.classList.remove("related"))}});
