  async function load(){
    const token=++state.loadToken,domain=state.domain;
    const keys=Object.keys(endpoints),results=await Promise.all(keys.map(k=>optional(endpointFor(k,domain))));
    if(token!==state.loadToken||domain!==state.domain)return;
    keys.forEach((k,i)=>state.remote[k]=results[i]);
    state.engagements=state.remote.engagements.ok?list(state.remote.engagements.data):[];
    state.tasks=state.remote.tasks.ok?list(state.remote.tasks.data):[];
    state.findings=state.remote.findings.ok?state.remote.findings.data:{verified:[],candidates:[]};
    state.readiness=state.remote.readiness.ok?state.remote.readiness.data:{};
    state.capabilities=state.remote.capabilities.ok?normalizeCaps(state.remote.capabilities.data):[];
    renderCampaign();renderTasks();renderTools();renderExtensions();renderFindings();renderVerification();renderVerificationDetailControls();
    if(state.verificationCandidateId)loadVerificationDetail();
    renderRuntime();renderOrchestration();loadAgentAuditSurfaces();
    if(["events","evidence"].some(id=>$("#"+id).classList.contains("active")))loadRunSurface(true);
    else{runSurfaceShell("events");runSurfaceShell("evidence")}
    if($("#hypotheses").classList.contains("active"))loadResearchCampaigns();
    if($("#evolution").classList.contains("active"))evolution.load();
    const select=$("#graphCampaign"),old=select.value;
    select.innerHTML=`<option value="">选择项目</option>${state.engagements.map(x=>`<option value="${esc(x.id)}">${esc(x.name||x.target||x.id)}</option>`).join("")}`;
    if(state.engagements.some(x=>String(x.id)===old))select.value=old;
    else select.value=state.engagements[0]?.id||"";
    if($("#graph").classList.contains("active"))loadGraph();
    const plannedMissing=new Set([]);
    const failureLabels={engagements:"Campaigns",tasks:"Task Center",findings:"Findings",readiness:"Runtime Readiness",capabilities:"Capability Registry",orchestration:"Orchestrator",agentAudits:"Agent Audit",verification:"Verification Registry",runtimeConfig:"Runtime Registry",runtimeUsage:"Runtime Usage",provider:"Provider"};
    const failures=keys.filter(k=>!state.remote[k].ok&&!(plannedMissing.has(k)&&state.remote[k].error?.status===404));
    $("#connectionBanner").hidden=failures.length===0;
    $("#connectionMessage").textContent=failures.length?`${failures.map(k=>failureLabels[k]).join("、")} 读取失败；相关页面已显示不可用状态。`:"";
  }

