  $("#researchCampaignForm").onsubmit=async e=>{e.preventDefault();const id=state.researchEngagementId;if(!id)return;const button=$("#researchCampaignForm [type=submit]");button.disabled=true;$("#researchCampaignMessage").textContent="正在创建…";try{const created=await post(`/api/v1/engagements/${encodeURIComponent(id)}/campaigns`,{name:$("#researchCampaignName").value.trim(),objective:$("#researchCampaignObjective").value.trim(),strategy:$("#researchCampaignStrategy").value});$("#researchCampaignDialog").close();state.researchCampaignId=created.id;await loadResearchCampaigns();toast("研究 Campaign 已创建；尚未启动任务")}catch(error){$("#researchCampaignMessage").textContent=`创建失败：${error.message}`}finally{button.disabled=false}};
