  function resetReportPreview(){state.reportToken++;const button=$("#reportExport");button.disabled=true;button.textContent="导出材料包";delete button.dataset.finding;delete button.dataset.platform;$("#reportPreview").textContent="选择 Verified Finding 后生成预览。";$("#reportQuality").replaceChildren();$("#reportProofState").textContent="";$("#reportMessage").textContent="来源或平台已变化，请重新生成预览。"}
  function renderReportQuality(check){const host=$("#reportQuality"),missing=list(check?.missing_required),recommended=list(check?.missing_recommended);host.innerHTML=`<div class="report-quality-status ${check?.ready?"ready":"incomplete"}"><strong>${check?.ready?"必填材料齐全，可供人工审核":"必填材料不完整，导出仅为待补草稿"}</strong><span>${missing.length} 项必填缺口 · ${recommended.length} 项建议缺口</span></div>${missing.length?`<details open><summary>必填缺口</summary><ul>${missing.map(x=>`<li><code>${esc(x)}</code></li>`).join("")}</ul></details>`:""}${recommended.length?`<details><summary>建议补充</summary><ul>${recommended.map(x=>`<li><code>${esc(x)}</code></li>`).join("")}</ul></details>`:""}<p>预览仅供人工复核，不会自动提交；完整度不代表事实已再次验证。</p>`}
