  function renderCommands(q=""){const term=q.trim().toLowerCase(),hits=VIEWS.filter(v=>[labels[v],commandAliases[v]].some(value=>value.toLowerCase().includes(term)));state.commandIndex=0;$("#commandResults").innerHTML=hits.map((v,i)=>`<button id="command-option-${v}" type="button" role="option" data-command="${v}" class="${i===0?"selected":""}" aria-selected="${i===0}"><span>${labels[v]}</span><small>${commandAliases[v]}</small></button>`).join("")||'<div class="empty-state" role="status"><b>没有匹配命令</b><p>尝试输入页面名称或中文关键词。</p></div>';if(hits.length)$("#commandInput").setAttribute("aria-activedescendant",`command-option-${hits[0]}`);else $("#commandInput").removeAttribute("aria-activedescendant")}
